import slugify from 'limax';

import { SPEAKING } from '~/config.mjs';
import snapshot from '~/data/speaking.json';

/**
 * Speaking data for the /speaking pages.
 *
 * The source of truth is README.json in the lirantal/public-speaking repo (generated by gigsboat).
 * It is fetched once per build; when the network is unavailable the committed snapshot in
 * src/data/speaking.json is used instead so builds never fail because of GitHub.
 */

export const SPEAKING_BASE = '/speaking';

/** Item types that count as a "talk" in the talk catalogue (podcasts and articles are media appearances). */
const TALK_TYPES = new Set(['conference', 'meetup', 'webinar', 'workshop']);

