const dateFormatters = {
	short: new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }),
	monthYear: new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric', timeZone: 'UTC' }),
	long: new Intl.DateTimeFormat('en-US', {
		weekday: 'long',
		month: 'long',
		day: 'numeric',
		year: 'numeric',
		timeZone: 'UTC',
	}),
};

/** @param {Date} date @param {'short' | 'monthYear' | 'long'} style */
export const formatDate = (date, style = 'short') => dateFormatters[style].format(date);

/** "23rd" style day of month, used in the big calendar date blocks. */
export const ordinalDay = (date) => {
	const day = date.getUTCDate();
	const suffix =
		day % 10 === 1 && day !== 11
			? 'st'
			: day % 10 === 2 && day !== 12
				? 'nd'
				: day % 10 === 3 && day !== 13
					? 'rd'
					: 'th';
	return { day, suffix };
};

export const countryFlag = (countryCode) =>
	countryCode ? String.fromCodePoint(...[...countryCode.toUpperCase()].map((c) => 0x1f1e6 + c.charCodeAt(0) - 65)) : '';

/** Twitter/X media URLs accept a size name; the source data often points at 4096x4096 originals. */
export const imageAtSize = (url, size = 'medium') =>
	/pbs\.twimg\.com\/media\//.test(url) ? url.replace(/([?&]name=)[^&]+/, `$1${size}`) : url;

export const youtubeThumbnail = (id) => `https://i.ytimg.com/vi/${id}/hqdefault.jpg`;

const compact = (list) => (Array.isArray(list) ? list : list ? [list] : []).filter((v) => typeof v === 'string' && v);

const youtubeId = (url) =>
	url.match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|live\/|embed\/)|youtu\.be\/)([\w-]{11})/)?.[1] ?? null;

const talkKey = (title) => title.toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');

const uniqueSlug = (base, used) => {
	let slug = base;
	for (let i = 2; used.has(slug); i++) slug = `${base}-${i}`;
	used.add(slug);
	return slug;
};

const socialHandle = (url) => {
	const match = url.match(/(?:twitter|x)\.com\/([^/?#]+)/i);
	return match ? `@${match[1]}` : new URL(url).hostname.replace(/^www\./, '');
};

async function loadSource() {
	try {
		const response = await fetch(SPEAKING.dataURL, { signal: AbortSignal.timeout(15_000) });
		if (!response.ok) throw new Error(`HTTP ${response.status}`);
		const data = await response.json();
		if (!Array.isArray(data?.items)) throw new Error('response has no items array');
		return { ...data, source: 'remote' };
	} catch (error) {
		console.warn(`[speaking] Could not fetch ${SPEAKING.dataURL} (${error.message}); using src/data/speaking.json`);
		return { ...snapshot, source: 'snapshot' };
	}
}

function buildEvents(items, now) {
	const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
	const usedSlugs = new Set();

	return items
		.filter((item) => item.status !== 'opted-out' && item.date && item.name)
		.map((item) => {
			const date = new Date(item.date);
			const title = item.title && item.title !== 'null' ? item.title.trim() : null;
			const recordings = [...new Set([...compact(item.recording_url), ...compact(item.youtube_urls)])];
			const videoIds = [...new Set(recordings.map(youtubeId).filter(Boolean))];
			const city = item.city || null;
			const country = item.country || null;
			const remote = !city && !country;
			const dateSlug = item.date.slice(0, 10);
			const slug = uniqueSlug([dateSlug, slugify(item.name) || item.type].join('-'), usedSlugs);

			return {
				slug,
				href: `${SPEAKING_BASE}/events/${slug}`,
				date,
				year: date.getUTCFullYear(),
				upcoming: date.getTime() >= today,
				name: item.name.trim(),
				title,
				type: TYPES[item.type] ? item.type : 'conference',
				isTalk: TALK_TYPES.has(item.type),
				url: item.url || null,
				slidesUrl: item.slides_url || null,
				recordings,
				videoIds,
				hasVideo: videoIds.length > 0,
				city,
				country,
				countryCode: remote ? null : item.country_code || null,
				flag: remote ? '' : countryFlag(item.country_code),
				remote,
				location: remote ? 'Online' : [city, country].filter(Boolean).join(', '),
				language: item.language || 'English',
				// LinkedIn media URLs in the source are signed and expire, so only keep durable image hosts.
				images: compact([...(item.images ?? []), ...compact(item.image_header)]).filter(
					(url) => !/licdn\.com/.test(url)
				),
				shoutouts: Object.entries(item.recognitions ?? {}).flatMap(([network, urls]) =>
					compact(urls).map((url) => ({ network, url, label: socialHandle(url) }))
				),
				resources: compact(item.resources),
				talk: null,
			};
		})
		.sort((a, b) => b.date - a.date);
}

function buildTalks(events) {
	const groups = new Map();
	for (const event of events) {
		if (!event.isTalk || !event.title) continue;
		const key = talkKey(event.title);
		if (!groups.has(key)) groups.set(key, []);
		groups.get(key).push(event);
	}

	const usedSlugs = new Set();
	const talks = [...groups.values()].map((deliveries) => {
		const latest = deliveries[0];
		const first = deliveries.at(-1);
		const titleVariants = [...new Set(deliveries.map((d) => d.title))];
		// events are sorted newest first, so this is the current title (skipping SHOUTED variants)
		const title = titleVariants.find((variant) => variant !== variant.toUpperCase()) ?? titleVariants[0];
		const topic = TOPICS.find((t) => t.match.test(title));
		const slug = uniqueSlug(slugify(title) || `talk-${first.date.toISOString().slice(0, 10)}`, usedSlugs);
		const past = deliveries.filter((d) => !d.upcoming);
		const upcoming = deliveries.filter((d) => d.upcoming).reverse();
		// prefer the most recent recording of a delivery that already happened
		const recording =
			[...past, ...upcoming].find((d) => d.hasVideo) ?? deliveries.find((d) => d.recordings.length) ?? null;

		const talk = {
			slug,
			href: `${SPEAKING_BASE}/talks/${slug}`,
			title,
			topic,
			deliveries,
			past,
			upcoming,
			count: deliveries.length,
			firstDate: first.date,
			lastDate: latest.date,
			firstYear: first.year,
			lastYear: latest.year,
			formats: [...new Set(deliveries.map((d) => d.type))],
			languages: [...new Set(deliveries.map((d) => d.language))],
			countries: [...new Set(deliveries.filter((d) => d.countryCode).map((d) => d.countryCode))],
			recording,
			recordingsCount: deliveries.filter((d) => d.recordings.length).length,
			slides: deliveries.filter((d) => d.slidesUrl),
			images: deliveries.flatMap((d) => d.images.map((src) => ({ src, event: d }))),
			titleVariants: titleVariants.map((variant) => {
				const uses = deliveries.filter((d) => d.title === variant);
				return { title: variant, count: uses.length, firstYear: uses.at(-1).year, lastYear: uses[0].year };
			}),
			// first given within the last six months (or not given yet)
			isNew: !past.length || Date.now() - first.date.getTime() < 183 * 24 * 60 * 60 * 1000,
		};
		for (const d of deliveries) d.talk = talk;
		return talk;
	});

	return talks.sort((a, b) => b.lastDate - a.lastDate || b.count - a.count);
}

function countBy(list, key) {
	const counts = new Map();
	for (const item of list) {
		const value = key(item);
		if (value) counts.set(value, (counts.get(value) ?? 0) + 1);
	}
	return [...counts.entries()].sort((a, b) => b[1] - a[1]);
}

function build(source) {
	const generatedAt = source.generatedAt ? new Date(source.generatedAt) : new Date();
	const events = buildEvents(source.items, new Date());
	const talks = buildTalks(events);
	const past = events.filter((e) => !e.upcoming);
	const upcoming = events.filter((e) => e.upcoming).reverse();
	const talkEvents = past.filter((e) => e.isTalk);
	const inPerson = events.filter((e) => e.countryCode);

	const countries = countBy(inPerson, (e) => e.countryCode).map(([code, count]) => {
		const sample = inPerson.find((e) => e.countryCode === code);
		return { code, count, flag: sample.flag, name: sample.country ?? code };
	});

	const years = countBy(events, (e) => String(e.year))
		.map(([year, count]) => ({
			year: Number(year),
			count,
			byType: Object.fromEntries(
				countBy(
					events.filter((e) => e.year === Number(year)),
					(e) => e.type
				)
			),
		}))
		.sort((a, b) => a.year - b.year);

	// A video is sometimes attached to several events (e.g. a repeat of the talk); list it once, under its oldest event.
	const seenVideos = new Set();
	const videos = [...events]
		.reverse()
		.filter((e) => e.hasVideo && !seenVideos.has(e.videoIds[0]) && seenVideos.add(e.videoIds[0]))
		.reverse();

	const types = Object.keys(TYPES)
		.map((type) => ({ type, ...TYPES[type], count: events.filter((e) => e.type === type).length }))
		.filter((t) => t.count);

	const topics = TOPICS.map((topic) => {
		const topicTalks = talks.filter((t) => t.topic === topic);
		return {
			...topic,
			talks: topicTalks,
			deliveries: topicTalks.reduce((sum, t) => sum + t.count, 0),
			flagship: [...topicTalks].sort((a, b) => b.count - a.count || b.lastDate - a.lastDate)[0],
		};
	}).filter((t) => t.talks.length);

	return {
		source: source.source,
		generatedAt,
		events,
		past,
		upcoming,
		talks,
		topics,
		types,
		countries,
		years,
		videos,
		media: events.filter((e) => e.type === 'podcast' || e.type === 'article'),
		stats: {
			appearances: events.length,
			talksDelivered: talkEvents.length,
			uniqueTalks: talks.length,
			countries: countries.length,
			cities: new Set(inPerson.filter((e) => e.city).map((e) => e.city)).size,
			videos: videos.length,
			podcasts: events.filter((e) => e.type === 'podcast').length,
			workshops: events.filter((e) => e.type === 'workshop').length,
			languages: new Set(events.map((e) => e.language)).size,
			firstYear: years[0]?.year,
			lastYear: past[0]?.year,
		},
	};
}

let cached;

/** Loads and normalizes speaking data once per build. */
export const getSpeaking = () => (cached ??= loadSource().then(build));
